static bool eqI(const char*a,const char*b){if(!a||!b)return false;for(;;++a,++b){char x=*a,y=*b;if(x>='A'&&x<='Z')x+=32;if(y>='A'&&y<='Z')y+=32;if(x!=y)return false;if(!x)return true;}}
