static const char* suffix(const char*cmd){if(startsI(cmd,"MoonMarker.DreamAvatar."))return cmd+23;if(startsI(cmd,"DreamAvatar."))return cmd+12;return 0;}
static const char* sharedSyncSuffix(const char*cmd){
    const char*s=0;
    if(startsI(cmd,"MoonMarker.DreamAvatar."))s=cmd+23;
    else if(startsI(cmd,"DreamAvatar."))s=cmd+12;
    else if(startsI(cmd,"MoonMarker.DreamWeapon."))s=cmd+23;
    else if(startsI(cmd,"DreamWeapon."))s=cmd+12;
    return s&&startsI(s,"Sync.")?s:0;
}
static bool isSync(const char*cmd){return sharedSyncSuffix(cmd)!=0;}
