static bool rebuild(void*o){if(!o||!executable(UPDATE_DISPLAY)){setCode("NATIVE_REBUILD_ADDRESS_UNAVAILABLE");return false;}if(!readable((unsigned char*)o+UNIT_MODEL_PTR_OFF,4,false)||!readable((unsigned char*)o+UNIT_DISPLAY_CACHE_OFF,4,false)){setCode("PLAYER_MODEL_STATE_UNAVAILABLE");return false;}((UpdateDisplayFn)UPDATE_DISPLAY)(o);__sync_synchronize();return true;}
