static bool refreshEquipment(void*o,unsigned long d){unsigned long cur=rd(d,DISPLAY_OFF);if(!cur){setCode("EQUIPMENT_REFRESH_DISPLAY_ZERO");return false;}unsigned long tmp=cur==EQUIP_TEMP_DISPLAY?EQUIP_FALLBACK_DISPLAY:EQUIP_TEMP_DISPLAY;wr(d,DISPLAY_OFF,tmp);__sync_synchronize();if(!rebuild(o)){wr(d,DISPLAY_OFF,cur);__sync_synchronize();return false;}wr(d,DISPLAY_OFF,cur);__sync_synchronize();if(!rebuild(o))return false;if(rd(d,DISPLAY_OFF)!=cur){setCode("EQUIPMENT_REFRESH_RESTORE_FAILED");return false;}return true;}
