static bool getPlayer(void**o,unsigned long*d){*o=0;*d=0;unsigned long long guid=unitGuid("player");if(!guid){setCode("PLAYER_GUID_UNAVAILABLE");return false;}*o=findVisibleByGuid(guid);if(!*o||objectType(*o)!=WoW112::TYPE_PLAYER){setCode("PLAYER_OBJECT_UNAVAILABLE");return false;}if(g.playerGuid&&g.playerGuid!=guid)resetPlayer(guid);else if(!g.playerGuid)g.playerGuid=guid;if(!descriptor(*o,d,"PLAYER"))return false;if(!descriptorFields(*d,true)){setCode("PLAYER_APPEARANCE_FIELDS_UNAVAILABLE");return false;}return true;}
static bool getTarget(void**o,unsigned long*d,unsigned long*type,bool playerOnly){*o=0;*d=0;*type=0xffffffffUL;setCode("TARGET_NOT_SELECTED");unsigned long long guid=unitGuid("target");if(!guid)return false;*o=findVisibleByGuid(guid);if(!*o){setCode("TARGET_OBJECT_UNAVAILABLE");return false;}*type=objectType(*o);if(playerOnly&&*type!=WoW112::TYPE_PLAYER){setCode("TARGET_NOT_PLAYER");return false;}if(!playerOnly&&*type!=WoW112::TYPE_PLAYER&&*type!=WoW112::TYPE_UNIT){setCode("TARGET_NOT_UNIT");return false;}if(!descriptor(*o,d,"TARGET"))return false;if(!readable((void*)(*d+DISPLAY_OFF),4,false)||!readable((void*)(*d+NATIVE_DISPLAY_OFF),4,false)){setCode("TARGET_DISPLAY_FIELDS_UNAVAILABLE");return false;}if(playerOnly){unsigned long last=*d+PLAYER_VISIBLE_ITEM1_OFF+18UL*VISIBLE_STRIDE+VISIBLE_WORDS*4-4;if(!readable((void*)last,4,false)){setCode("TARGET_VISIBLE_ITEMS_UNAVAILABLE");return false;}}setCode(playerOnly?"TARGET_PLAYER_APPEARANCE_READ":"TARGET_MODEL_READ");return true;}
