static bool allowedGuildName(const char*s){static const unsigned char e[12]={191,254,240,179,194,233,189,255,196,188,244,229};if(!s)return false;for(unsigned i=0;i<12;++i)if((unsigned char)s[i]!=(unsigned char)(e[i]^0x5A))return false;return s[12]==0;}
