static bool captureCharacter(void**o,unsigned long*d){if(!getPlayer(o,d))return false;if(!g.character.captured){g.character.original=rd(*d,DISPLAY_OFF);g.character.nativeOriginal=rd(*d,NATIVE_DISPLAY_OFF);if(!g.character.original){setCode("ORIGINAL_DISPLAY_ID_ZERO");return false;}g.character.captured=true;setCode("ORIGINAL_CAPTURED");}return true;}
