static bool restoreCharacter(){void*o=0;unsigned long d=0;if(!captureCharacter(&o,&d))return false;wr(d,DISPLAY_OFF,g.character.original);__sync_synchronize();if(rd(d,DISPLAY_OFF)!=g.character.original){setCode("RESTORE_WRITE_VERIFY_FAILED");return false;}if(!rebuild(o))return false;g.character.requested=0;g.character.applied=false;setCode("RESTORED_NATIVE_MODEL_REBUILD");return true;}
