static bool maintainCharacter(){if(!g.character.autoMaintain||!g.character.applied||!g.character.requested){setCode("MAINTAIN_IDLE");return true;}void*o=0;unsigned long d=0;if(!captureCharacter(&o,&d))return false;if(rd(d,DISPLAY_OFF)!=g.character.requested){wr(d,DISPLAY_OFF,g.character.requested);__sync_synchronize();if(rd(d,DISPLAY_OFF)!=g.character.requested){setCode("MAINTAIN_WRITE_VERIFY_FAILED");return false;}if(!rebuild(o))return false;setCode("MAINTAIN_REAPPLIED_NATIVE");}else setCode("MAINTAIN_OK");return true;}
