static Snapshot localSnapshot(){Snapshot s={};if(g.character.applied){s.flags|=SYNC_CHARACTER;s.character=g.character.requested;}if(g.weapons.applied[0]){s.flags|=SYNC_WMAIN;s.wmain=g.weapons.requested[0];}if(g.weapons.applied[1]){s.flags|=SYNC_WOFF;s.woff=g.weapons.requested[1];}if(g.weapons.applied[2]){s.flags|=SYNC_WRANGED;s.wranged=g.weapons.requested[2];}if(g.glows.applied[0]){s.flags|=SYNC_GMAIN;s.gmain=g.glows.requested[0];}if(g.glows.applied[1]){s.flags|=SYNC_GOFF;s.goff=g.glows.requested[1];}if(g.mount.applied){s.flags|=SYNC_MOUNT;s.mount=g.mount.requested;}return s;}
static bool snapshotValid(const Snapshot&s){return (s.flags&~DA_ALLOWED_FLAGS)==0&&s.character<=MAX_ID&&s.wmain<=MAX_ID&&s.woff<=MAX_ID&&s.wranged<=MAX_ID&&s.gmain<=MAX_ID&&s.goff<=MAX_ID&&s.mount<=MAX_ID&&(!(s.flags&SYNC_CHARACTER)||s.character!=0);}
