static bool put8(Buf&b,unsigned v){if(b.n+1>sizeof(b.d))return false;b.d[b.n++]=(unsigned char)v;return true;}static bool put16(Buf&b,unsigned v){return put8(b,v)&&put8(b,v>>8);}static bool put32(Buf&b,unsigned long v){for(int i=0;i<4;++i)if(!put8(b,v>>(8*i)))return false;return true;}static bool put64(Buf&b,unsigned long long v){for(int i=0;i<8;++i)if(!put8(b,(unsigned)(v>>(8*i))))return false;return true;}
