static unsigned long epochNow(){SYSTEMTIME t={};GetSystemTime(&t);auto leap=[](unsigned y){return (y%4==0&&y%100!=0)||y%400==0;};static const unsigned md[12]={31,28,31,30,31,30,31,31,30,31,30,31};unsigned long days=0;for(unsigned y=1970;y<t.wYear;++y)days+=leap(y)?366:365;for(unsigned m=1;m<t.wMonth;++m){days+=md[m-1];if(m==2&&leap(t.wYear))days++;}days+=t.wDay-1;return days*86400UL+t.wHour*3600UL+t.wMinute*60UL+t.wSecond;}
