static bool buildPacket(const Snapshot&s,const char*sender,char*out,unsigned cap,const char**reason){if(!sender||!*sender){*reason="DA_PACKET_SENDER_REQUIRED";return false;}if(!snapshotValid(s)){*reason="DA_PACKET_VALUES_INVALID";return false;}Buf b={};unsigned long issued=epochNow(),nonce=++nonceCounter;put8(b,DA_PACKET_VERSION);put16(b,s.flags);put32(b,s.character);put32(b,s.wmain);put32(b,s.woff);put32(b,s.wranged);put32(b,s.gmain);put32(b,s.goff);put32(b,s.mount);put32(b,issued);put32(b,nonce);put32(b,nameHash(sender));put64(b,mac(b.d,b.n));if(!b64enc(b,out,cap)||slen(out)>245){*reason="DA_PACKET_TOO_LONG";return false;}*reason="OK";return true;}
