static SenderSnapshot* senderSlot(const char*sender,bool create){char n[64]={};normalizeSender(sender,n,sizeof(n));SenderSnapshot*empty=0;for(auto&s:senders){if(s.active&&eqI(s.sender,n))return &s;if(!s.active&&!empty)empty=&s;}if(create&&empty){*empty=SenderSnapshot{};empty->active=true;cpy(empty->sender,sizeof(empty->sender),n);return empty;}return 0;}
